document.addEventListener('DOMContentLoaded', function () {
    'use strict';
    const slider = document.querySelector('#osm-home-products-slider');
    const prevBtn = document.querySelector('#osm-home-products-prev');
    const nextBtn = document.querySelector('#osm-home-products-next');
    if (slider && prevBtn && nextBtn) {
        prevBtn.addEventListener('click', function () {
            slider.scrollBy({ left: -240, behavior: 'smooth' });
        });
        nextBtn.addEventListener('click', function () {
            slider.scrollBy({ left: 240, behavior: 'smooth' });
        });
    }
});